#!/usr/bin/env bash
#
# A wizard — walks a human through a bounded real Ark route-fallback probe.
# Generated by the /zj-wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} )) && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# STAGES — one deliberate, bounded, read-only real Ark route-fallback probe.

TOTAL_STAGES=5
ENV_FILE=/dev/null
SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
REPO_ROOT=$(cd -- "$SCRIPT_DIR/.." && pwd)
RUNNER="${SCRIPT_DIR}/run_real_ark_failover.py"
ENDPOINT="https://ark.cn-beijing.volces.com/api/coding/v3/responses"
MODEL="ark-code-latest"
PRIMARY_MODEL="${ZWB_ARK_PRIMARY_MODEL:-__zworkbench_invalid_model__}"
REGION="${ZWB_ARK_REGION:-cn-beijing}"
PROJECT_FINGERPRINT="${ZWB_ARK_PROJECT_FINGERPRINT:-}"
EVIDENCE_ROOT="${ZWB_ARK_FAILOVER_EVIDENCE_DIR:-${REPO_ROOT}/evaluation/evidence/real-ark-failover}"
ARK_API_KEY="${ARK_API_KEY:-}"
EVIDENCE_DIR=""

trap 'unset ARK_API_KEY' EXIT HUP INT TERM

banner "Real Ark route-fallback staging"

stage "Scope — deliberate negative-control fallback"
say "This is an opt-in acceptance/evaluation probe, not the default ZWorkbench Provider route."
open_url "https://www.volcengine.com/docs/82379/1928261?lang=zh"
step "The primary route deliberately uses an invalid model so Ark rejects it; the fallback uses $MODEL."
step "Both routes use the fixed endpoint $ENDPOINT, one synthetic read-only request each, and no automatic retry."
step "This proves real Ark route fallback for a controlled rejection; it does not prove a transient outage or a second independent Provider."
if ! confirm "Proceed to account and safety checks before any key is requested?"; then
  say "Stopped before any credential was requested or network access occurred."
  exit 0
fi

stage "Preflight — account identity and exit gates"
say "Confirm the actual Ark account/data region and project/billing scope in the Provider console."
step "Region is fixed to cn-beijing; the endpoint hostname alone is not proof."
if [[ -z "$PROJECT_FINGERPRINT" ]]; then
  ask PROJECT_FINGERPRINT "Ark Project/billing ID SHA-256 fingerprint [64 hex]:"
else
  note "Using existing local ZWB_ARK_PROJECT_FINGERPRINT value; it will not be displayed or rewritten."
fi
if [[ "$REGION" != "cn-beijing" || ! "$PROJECT_FINGERPRINT" =~ ^[0-9A-Fa-f]{64}$ ]]; then
  warn "Region or project fingerprint is invalid; stopping before credential input."
  exit 1
fi
step "Do not use ZWorkbench, a local workspace/project name, model, endpoint, region, API Key, or API Key fingerprint as the project fingerprint."
if ! confirm "Have you confirmed Provider/model/project identity and region?"; then exit 1; fi
if ! confirm "Have you confirmed API key scope and its disable/delete/revocation path?"; then exit 1; fi
if ! confirm "Have you confirmed Coding endpoint data categories, retention, and deletion basis?"; then exit 1; fi
if ! confirm "Have you inventoried task/run/queue, Webhook, backup, file, and response resources?"; then exit 1; fi
if ! confirm "Have you confirmed the stop, cleanup, and Provider-side exit owner/path?"; then exit 1; fi
if ! confirm "Do you authorize exactly two independent synthetic read-only requests now, with no retries?"; then exit 1; fi

stage "Credential — hidden and ephemeral"
if [[ -n "$ARK_API_KEY" ]]; then
  note "Using the existing local ARK_API_KEY reference; its value will not be displayed or persisted."
else
  ask_secret ARK_API_KEY "Ark API key:"
fi
if [[ -z "$ARK_API_KEY" ]]; then
  warn "No key entered; stopping before network access."
  exit 1
fi

stage "Probe — real Ark primary rejection then fallback"
stamp=$(date -u +%Y%m%dT%H%M%SZ)
EVIDENCE_DIR="${EVIDENCE_ROOT}/${stamp}-$$"
mkdir -m 700 -p "$EVIDENCE_DIR"
say "Evidence directory: $EVIDENCE_DIR"
say "The runner reads the key through stdin, never stores raw request/response bodies, and records only redacted shapes and owner ledger facts."
if ! printf '%s' "$ARK_API_KEY" | python3 "$RUNNER" \
  --output "$EVIDENCE_DIR" \
  --region "$REGION" \
  --project-fingerprint "$PROJECT_FINGERPRINT" \
  --primary-model "$PRIMARY_MODEL" \
  --fallback-model "$MODEL" \
  --budget-requests 2 \
  --max-duration-seconds 30 \
  --key-scope-confirmed \
  --data-retention-confirmed \
  --remote-inventory-confirmed \
  --exit-path-confirmed \
  --one-time-authorization-confirmed; then
  warn "The real Ark fallback probe did not complete successfully; keep only the redacted summary for diagnosis and do not retry automatically."
fi

stage "Evidence — cleanup and handoff"
unset ARK_API_KEY
say "The API key has been removed from this wizard's shell variable."
say "Only share $EVIDENCE_DIR/case/summary.json. It contains no raw key, request body, or response body."
say "A successful controlled fallback does not authorize production data, writes, tasks, Webhooks, backups, or account deletion."

finish
